99	struct SampleConfig {
100	    float temperature = 1.0f;
101	    int top_k = 0;
102	    float top_p = 1.0f;
103	    bool do_sample = false;
104	};
105	
106	class ncnn_llm_base {
107	protected:
108	    bool use_vulkan_ = false;
109	    int num_threads_ = 4;
110	    bool ok_ = true;
111	    std::mt19937 rng_{std::random_device{}()};
112	
113	    ncnn_llm_base(bool use_vulkan = false, int num_threads = 4)
114	        : use_vulkan_(use_vulkan), num_threads_(num_threads) {
115	#if NCNN_VULKAN
116	        if (use_vulkan_) {
117	            ncnn::create_gpu_instance();
118	        }
119	#endif
120	    }
121	
122	    virtual ~ncnn_llm_base() {
123	#if NCNN_VULKAN
124	        if (use_vulkan_) {
125	            ncnn::destroy_gpu_instance();
126	        }
127	#endif
128	    }
129	
130	    ncnn::Option create_option() const {
131	        ncnn::Option opt;
132	        opt.num_threads = num_threads_;
133	        opt.use_bf16_storage = false;
134	        opt.use_vulkan_compute = use_vulkan_;
135	        return opt;
136	    }
137	
138	    bool load_net(ncnn::Net& net, const std::string& param_path, const std::string& bin_path) {
139	        if (net.load_param(param_path.c_str()) != 0 ||
140	            net.load_model(bin_path.c_str()) != 0) {
141	            ok_ = false;
142	            return false;
143	        }
144	        return true;
145	    }
146	
147	    int sample_logits(const ncnn::Mat& logits, const SampleConfig& cfg) {
148	        if (!cfg.do_sample) {
149	            return argmax1d(logits);
150	        }
151	
152	        std::vector<float> probs(logits.w);
153	        const float* p = logits;
154	        for (int i = 0; i < logits.w; ++i) {
155	            probs[i] = p[i];
156	        }
157	
158	        softmax_vec(probs, cfg.temperature);
159	
160	        if (cfg.top_k > 0) {
161	            apply_top_k(probs, cfg.top_k);
162	        }
163	
164	        if (cfg.top_p < 1.0f) {
165	            apply_top_p(probs, cfg.top_p);
166	        }
167	
168	        return sample_from_probs(probs);
169	    }
170	
171	private:
172	    void softmax_vec(std::vector<float>& logits, float temperature) {
173	        float max_logit = *std::max_element(logits.begin(), logits.end());
174	        float sum = 0.f;
175	        for (float& x : logits) {
176	            x = std::exp((x - max_logit) / temperature);
177	            sum += x;
178	        }
179	        for (float& x : logits) x /= sum;
180	    }
181	
182	    void apply_top_k(std::vector<float>& probs, int k) {
183	        if (k <= 0 || k >= (int)probs.size()) return;
184	        std::vector<float> tmp = probs;
185	        std::nth_element(tmp.begin(), tmp.end() - k, tmp.end());
186	        float threshold = tmp[tmp.size() - k];
187	        for (float& p : probs) if (p < threshold) p = 0.f;
188	    }
189	
190	    void apply_top_p(std::vector<float>& probs, float p) {
191	        if (p >= 1.0f) return;
192	        std::vector<std::pair<float,int>> v;
193	        v.reserve(probs.size());
194	        for (int i = 0; i < (int)probs.size(); ++i) {
195	            v.emplace_back(probs[i], i);
196	        }
197	        std::sort(v.begin(), v.end(), std::greater<>());
198	
199	        float cum = 0.f;
200	        size_t cutoff = v.size();
201	        for (size_t i = 0; i < v.size(); ++i) {
202	            cum += v[i].first;
203	            if (cum >= p) {
204	                cutoff = i + 1;
205	                break;
206	            }
207	        }
208	        std::vector<char> keep(probs.size(), 0);
209	        for (size_t i = 0; i < cutoff; ++i) {
210	            keep[v[i].second] = 1;
211	        }
212	        for (int i = 0; i < (int)probs.size(); ++i) {
213	            if (!keep[i]) probs[i] = 0.f;
214	        }
215	    }
216	
217	    int sample_from_probs(const std::vector<float>& probs) {
218	        std::discrete_distribution<int> dist(probs.begin(), probs.end());
219	        return dist(rng_);
220	    }
221	
222	public:
223	    bool ok() const { return ok_; }
224	};

